class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        starts = [(i, 0) for i in range(n)] + [(0, j) for j in range(1, n)]
        for r, c in starts:
            cells = []
            i, j = r, c
            while i < n and j < n:
                cells.append((i, j))
                i += 1
                j += 1
            vals = [grid[x][y] for x, y in cells]
            if r >= c:
                vals.sort(reverse=True)
            else:
                vals.sort()
            for (x, y), v in zip(cells, vals):
                grid[x][y] = v
        return grid
