from collections import defaultdict

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        diags = defaultdict(list)
        for r in range(n):
            for c in range(n):
                diags[r - c].append(grid[r][c])
        for d in diags:
            if d >= 0:
                diags[d].sort(reverse=True)
            else:
                diags[d].sort()
        ptr = defaultdict(int)
        res = [[0] * n for _ in range(n)]
        for r in range(n):
            for c in range(n):
                d = r - c
                res[r][c] = diags[d][ptr[d]]
                ptr[d] += 1
        return res
